CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text,display_name text NOT NULL,role text NOT NULL DEFAULT 'listener',country_code char(2),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS artists(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,bio text,verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS albums(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),artist_id uuid REFERENCES artists(id) ON DELETE CASCADE,title text NOT NULL,artwork_url text,release_date date,kind text NOT NULL DEFAULT 'album');
CREATE TABLE IF NOT EXISTS tracks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),album_id uuid REFERENCES albums(id) ON DELETE SET NULL,artist_id uuid REFERENCES artists(id) ON DELETE SET NULL,title text NOT NULL,duration_ms int NOT NULL DEFAULT 0,isrc text UNIQUE,audio_key text,explicit boolean NOT NULL DEFAULT false,lossless boolean NOT NULL DEFAULT false,hires boolean NOT NULL DEFAULT false,atmos boolean NOT NULL DEFAULT false,territories text[] NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS playlists(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid REFERENCES users(id) ON DELETE CASCADE,title text NOT NULL,description text,is_public boolean NOT NULL DEFAULT false,collaborative boolean NOT NULL DEFAULT false,cover_url text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS playlist_tracks(playlist_id uuid REFERENCES playlists(id) ON DELETE CASCADE,track_id uuid REFERENCES tracks(id) ON DELETE CASCADE,position int NOT NULL,added_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(playlist_id,track_id));
CREATE TABLE IF NOT EXISTS likes(user_id uuid REFERENCES users(id) ON DELETE CASCADE,track_id uuid REFERENCES tracks(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,track_id));
CREATE TABLE IF NOT EXISTS follows(user_id uuid REFERENCES users(id) ON DELETE CASCADE,artist_id uuid REFERENCES artists(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,artist_id));
CREATE TABLE IF NOT EXISTS listening_events(id bigserial PRIMARY KEY,user_id uuid REFERENCES users(id) ON DELETE SET NULL,track_id uuid REFERENCES tracks(id) ON DELETE SET NULL,event_type text NOT NULL,position_ms int DEFAULT 0,session_id uuid,device_id text,country_code char(2),occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS listening_events_user_time ON listening_events(user_id,occurred_at DESC); CREATE INDEX IF NOT EXISTS tracks_title_idx ON tracks USING gin(to_tsvector('simple',title));
CREATE TABLE IF NOT EXISTS subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id) ON DELETE CASCADE,provider text NOT NULL,status text NOT NULL,plan text NOT NULL,provider_ref text UNIQUE,current_period_end timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rights(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),track_id uuid REFERENCES tracks(id) ON DELETE CASCADE,territory char(2) NOT NULL,start_at timestamptz,end_at timestamptz,master_ok boolean NOT NULL DEFAULT false,publishing_ok boolean NOT NULL DEFAULT false,UNIQUE(track_id,territory));
CREATE TABLE IF NOT EXISTS royalty_ledger(id bigserial PRIMARY KEY,track_id uuid REFERENCES tracks(id),artist_id uuid REFERENCES artists(id),user_id uuid REFERENCES users(id),period date NOT NULL,units numeric(18,6) NOT NULL DEFAULT 0,revenue numeric(18,6) NOT NULL DEFAULT 0,currency char(3) NOT NULL DEFAULT 'USD');
